# ─── grammar ─────────────────────────────────────────────────────────────────────

def _split(text: str, sep: str) -> list[str]:
    """Split on `sep` outside double quotes and brackets."""
    out, cur, quote, depth, i = [], "", False, 0, 0
    while i < len(text):
        ch = text[i]
        if not quote and depth == 0 and text.startswith(sep, i):
            out.append(cur); cur = ""; i += len(sep); continue
        if ch == '"':
            quote = not quote
        elif not quote and ch == "[":
            depth += 1
        elif not quote and ch == "]":
            depth -= 1
        cur += ch; i += 1
    out.append(cur)
    return out


def _fault(cond: str, clause: str, why: str) -> GateFault:
    return GateFault(f"the condition `{cond}` is outside the discovery grammar: `{clause}` — {why} "
                     "(KEY exists | KEY ==/!= VALUE | KEY IN/NOT IN [VALUE, …], joined by AND / OR)")


def _value(cond: str, clause: str, raw: str):
    v = raw.strip()
    if not v:
        raise _fault(cond, clause, "a value is missing")
    if v.startswith('"'):
        if len(v) < 2 or not v.endswith('"') or '"' in v[1:-1]:
            raise _fault(cond, clause, f"`{v}` is not one quoted value")
        return v[1:-1]
    if v == "null":
        return None
    if v in ("true", "false"):
        return v == "true"
    if re.fullmatch(r"-?\d+", v):
        return int(v)
    if re.fullmatch(r"-?\d+\.\d+", v):
        return float(v)
    if re.search(r"(?:^|\s)(?:AND|OR|IN|NOT)(?:\s|$)", v):
        raise _fault(cond, clause, f"`{v}` carries a keyword — a dangling AND / OR, or a misspelt operator")
    if re.search(r'["\[\],=!<>~]', v):
        raise _fault(cond, clause, f"`{v}` is not a value (quote it, or use a bare token without quotes, brackets, commas or operators)")
    return v


def parse(cond) -> list[list[dict]]:
    """A condition → its AST: a list of conjunctions (OR), each a list of clauses (AND). GateFault when it does not parse."""
    if not isinstance(cond, str) or not cond.strip():
        raise _fault(str(cond), str(cond), "the condition is empty")
    cond = cond.strip()
    ast = []
    for conj in _split(cond, " OR "):
        clauses = []
        for raw in _split(conj, " AND "):
            c = raw.strip()
            if not c:
                raise _fault(cond, raw, "an empty clause (a dangling AND / OR)")
            m = re.fullmatch(rf"({KEY}) exists", c)
            if m:
                clauses.append({"key": m.group(1), "op": "exists"}); continue
            m = re.fullmatch(rf"({KEY}) (NOT IN|IN) \[(.*)\]", c)
            if m:
                items = [x for x in _split(m.group(3), ",")]
                if not m.group(3).strip():
                    raise _fault(cond, c, "an empty list")
                clauses.append({"key": m.group(1), "op": m.group(2), "values": [_value(cond, c, x) for x in items]}); continue
            m = re.fullmatch(rf"({KEY}) ?(==|!=) ?(.*)", c)
            if m:
                clauses.append({"key": m.group(1), "op": m.group(2), "value": _value(cond, c, m.group(3))}); continue
            raise _fault(cond, c, "not a clause")
        ast.append(clauses)
    return ast


def canon(v) -> str:
    """One comparable form: null, true/false, numbers and strings as their literal text."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


def flatten(fm: dict, prefix: str = "") -> dict:
    """Nested frontmatter → {dotted key: leaf value}; a dotted key stays as it is; a list is a leaf."""
    out = {}
    for k, v in (fm or {}).items():
        dk = f"{prefix}{k}"
        if isinstance(v, dict) and v:
            out.update(flatten(v, dk + "."))
        else:
            out[dk] = v
    return out


def _has_value(v) -> bool:
    return v is not None and v != "None" and v != "" and v != [] and v != {}


def _exists(key: str, answers: dict) -> bool:
    return any(_has_value(v) for k, v in answers.items() if k == key or k.startswith(key + "."))


def _clause(c: dict, answers: dict) -> bool:
    if c["op"] == "exists":
        return _exists(c["key"], answers)
    v = answers.get(c["key"])
    if isinstance(v, (list, dict)):
        raise GateFault(f"`{c['key']}` holds a list; a list answer may only be tested with `exists`")
    if c["op"] in ("!=", "NOT IN") and v is None:
        return False   # a null key never differs: `!=` / `NOT IN` hold only for a key that holds an answer
    if c["op"] in ("==", "!="):
        same = canon(v) == canon(c["value"])
        return same if c["op"] == "==" else not same
    inside = canon(v) in {canon(x) for x in c["values"]}
    return inside if c["op"] == "IN" else not inside


def evaluate(ast: list[list[dict]], answers: dict) -> bool:
    return any(all(_clause(c, answers) for c in conj) for conj in ast)


# ─── registry ────────────────────────────────────────────────────────────────────

def load_registry(repo: Path) -> dict:
    p = repo / REGISTRY
    if not p.is_file():
        raise GateFault(f"the discovery registry {REGISTRY} is absent — the questions SETUP asks, their options and their conditions live there (EVOL-102); write it, then re-run")
    try:
        reg = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"the discovery registry {REGISTRY} is not readable JSON ({e})") from None
    if not isinstance(reg, dict) or not isinstance(reg.get("questions"), list):
        raise GateFault(f"the discovery registry {REGISTRY} carries no `questions` list")
    return reg


def _questions(reg: dict) -> list[dict]:
    return [q for q in reg.get("questions", []) if isinstance(q, dict)]


def _specs(reg: dict) -> dict:
    """{key: spec} over every question (first declaration wins; V1 reports duplicates)."""
    out = {}
    for q in _questions(reg):
        for k, s in (q.get("keys") or {}).items() if isinstance(q.get("keys"), dict) else []:
            out.setdefault(k, s if isinstance(s, dict) else {})
    return out


def _derived(reg: dict) -> dict:
    d = reg.get("derived")
    return d if isinstance(d, dict) else {}


def _offered(spec: dict) -> list[str] | None:
    """The closed literals of a key (canonical text), or None for a free key."""
    if isinstance(spec.get("options"), list):
        return sorted({canon(x) for x in spec["options"]})
    ob = spec.get("options_by")
    if isinstance(ob, dict) and isinstance(ob.get("values"), dict):
        return sorted({canon(x) for vals in ob["values"].values() if isinstance(vals, list) for x in vals})
    return None


def _known(spec: dict) -> set[str]:
    """Every literal the registry models for a key (EVOL-131): its options, the values an earlier answer decides, its configures rows."""
    db = spec.get("decided_by") if isinstance(spec.get("decided_by"), dict) else {}
    dec = db.get("values") if isinstance(db.get("values"), dict) else {}
    rows = spec.get("configures") if isinstance(spec.get("configures"), dict) else {}
    return set(_offered(spec) or []) | {canon(v) for v in dec.values()} | {canon(r) for r in rows}


def decided(reg: dict, ans: dict) -> dict:
    """{key: value} — the asked keys an earlier answer decides (`decided_by`), for an answer set that leaves them null;
    only where the key's question is owed (its `when` holds) — an engine the pack does not cover decides nothing."""
    out = {}
    owed = {k for q in _questions(reg) if _owed(reg, q, ans) for k in ((q.get("keys") or {}) if isinstance(q.get("keys"), dict) else {})}
    for k, s in _specs(reg).items():
        db = s.get("decided_by")
        if k not in owed or not isinstance(db, dict) or not isinstance(db.get("values"), dict) or ans.get(db.get("key")) is None:
            continue
        v = db["values"].get(canon(ans.get(db["key"])))
        if v is not None:
            out[k] = v
    out.update(matched(reg, ans)[0])
    return out


def matched(reg: dict, ans: dict) -> tuple[dict, list[str]]:
    """EVOL-079 — the derived keys a free answer selects (`matches`): {key: value} and the warnings of every `else`."""
    out, warn = {}, []
    for k, s in _derived(reg).items():
        m = s.get("matches") if isinstance(s, dict) else None
        if not isinstance(m, dict) or not isinstance(m.get("values"), dict) or ans.get(m.get("key")) in (None, ""):
            continue
        text = canon(ans[m["key"]]).lower()
        hit = next((v for sub, v in m["values"].items() if sub.lower() in text), None)
        if hit is None:
            hit = m.get("else")
            warn.append(str(m.get("warn") or "").replace("{answer}", clean(canon(ans[m["key"]]), 200)))   # the user's text: no control byte reaches the terminal
        out[k] = hit
    return out, warn


def with_decided(reg: dict, ans: dict) -> dict:
    """The answer set the conditions read: the answers plus every value they decide (an answered key keeps its answer)."""
    return {**ans, **{k: v for k, v in decided(reg, ans).items() if ans.get(k) is None}}


def load_manifest(repo: Path) -> dict:
    p = repo / MANIFEST
    try:
        m = json.loads(p.read_text(encoding="utf-8"))
    except FileNotFoundError:
        raise GateFault(f"the governance manifest {MANIFEST} is absent — the template entries and their conditions live there") from None
    except (OSError, ValueError) as e:
        raise GateFault(f"the governance manifest {MANIFEST} is not readable JSON ({e})") from None
    return m if isinstance(m, dict) else {}


def check(ast: list[list[dict]], reg: dict) -> list[str]:
    """What a condition names that the registry does not hold: an unknown key, a prefix compared, a list compared, a
    literal outside the key's options."""
    specs, derived = _specs(reg), _derived(reg)
    known = set(specs) | set(derived)
    out = []
    for conj in ast:
        for c in conj:
            k = c["key"]
            if k not in known:
                if any(x.startswith(k + ".") for x in known):
                    if c["op"] != "exists":
                        out.append(f"`{k}` is a prefix of registry keys — a prefix may only be tested with `exists`")
                else:
                    out.append(f"`{k}` is not a registry or derived key")
                continue
            spec = specs.get(k, {})
            if c["op"] == "exists":
                continue
            if spec.get("free") in ("list", "references"):
                out.append(f"`{k}` is a list answer — it may only be tested with `exists`")
                continue
            m = derived.get(k, {}).get("matches") if isinstance(derived.get(k), dict) else None
            if k in derived and not isinstance(m, dict):
                continue   # a derived key: computed, no list to hold a literal to
            if isinstance(m, dict):   # a matched key (EVOL-079): its values and its else
                offered = sorted({canon(x) for x in [*(m.get("values") or {}).values(), m.get("else")] if x is not None})
                for lit in ([c["value"]] if "value" in c else c["values"]):
                    if lit is not None and canon(lit) not in offered:
                        out.append(f"`{canon(lit)}` is not a value of `{k}` ({' | '.join(offered)})")
                continue
            offered = _offered(spec)
            if offered is None:   # free text: only its suggestions (or null) — a literal nobody offers is drift
                offered = sorted({canon(x) for x in spec.get("suggestions") or [] if isinstance(spec.get("suggestions"), list)})
            for lit in ([c["value"]] if "value" in c else c["values"]):
                if lit is not None and canon(lit) not in offered:
                    out.append(f"`{canon(lit)}` is not offered for `{k}` ({' | '.join(offered) or 'free text without suggestions: compare it only to null'})")
    return out


# ─── answers + resolve + eval ────────────────────────────────────────────────────

def answers(repo: Path, file: Path | None = None) -> dict:
    """The answer set: a fixture file `{"answers": {...}}`, else the docs/setup.md frontmatter; flattened."""
    if file is not None:
        try:
            doc = json.loads(Path(file).read_text(encoding="utf-8"))
        except (OSError, ValueError) as e:
            raise GateFault(f"the answers file {file} is not readable JSON ({e})") from None
        if not isinstance(doc, dict) or not isinstance(doc.get("answers"), dict):
            raise GateFault(f"the answers file {file} carries no `answers` object ({{\"answers\": {{\"<dotted key>\": value}}}})")
        ans = flatten(doc["answers"])
        reg = load_registry(repo)
        known = set(_specs(reg)) | set(_derived(reg)) | {p for s in _specs(reg).values() if isinstance(s.get("configures"), dict)
                                                         for r in s["configures"].values() if isinstance(r, dict) for p in r} \
            | {s["carries"]["from"] for s in _specs(reg).values() if isinstance(s.get("carries"), dict) and isinstance(s["carries"].get("from"), str)}
        unknown = [k for k in ans if not any(k == r or k.startswith(r + ".") for r in known)]
        if unknown:
            raise GateFault(f"the answers file {file} answers {', '.join(f'`{k}`' for k in unknown)} — not a registry or derived key "
                            f"(a typo, or a question the registry {REGISTRY} does not ask)")
        return _carry(reg, ans)
    p = repo / SETUP_MD
    if not p.is_file():
        raise GateFault(f"the answer home {SETUP_MD} is absent — SETUP creates it at the start of discovery; run SETUP, or pass --answers FILE")
    text = p.read_text(encoding="utf-8", errors="replace")
    m = FM_RE.match(text)
    if not m:
        raise GateFault(f"the answer home {SETUP_MD} has no readable frontmatter (a `---` fence at the top, YAML inside) — the answers live there")
    data = parse_yaml(m.group(1))
    if not isinstance(data, dict):
        raise GateFault(f"the answer home {SETUP_MD} frontmatter is not a mapping — the answers live there as `key: value` lines")
    return _carry(load_registry(repo), flatten(data))


def _carry(reg: dict, ans: dict) -> dict:
    """EVOL-132 — a retired key's answer read under the key that carries it, verbatim, while that key is unanswered: one home."""
    out = dict(ans)
    for k, s in _specs(reg).items():
        c = s.get("carries")
        if not isinstance(c, dict) or not isinstance(c.get("from"), str) or _has_value(out.get(k)):
            continue
        old = out.pop(c["from"], None)
        vals = [x for x in (old if isinstance(old, list) else [old]) if x is not None and str(x).strip() and str(x) != "None"]
        if vals:
            out[k] = [{"name": str(x).strip(), "for": c.get("for"), "carried_from": c["from"]} for x in vals]
    return out


def _carried_only(v) -> bool:
    return isinstance(v, list) and bool(v) and all(isinstance(e, dict) and e.get("carried_from") for e in v)


def _one_line(s: str) -> bool:
    return len(s) <= REFERENCE_TEXT_MAX and s.isprintable()


def _netloc(link: str) -> str:
    try:
        return urlsplit(link.strip()).netloc
    except ValueError:   # a malformed host (`https://[x`): no netloc to trust — read as one carrying a credential
        return "@"


def _reference_problems(v) -> list[str]:
    """EVOL-132 — what a `free: references` answer may not be (None: unanswered)."""
    if v is None:
        return []
    if not isinstance(v, list) or not v:
        return ["is not a list of reference products — name at least one, each `{name, for}`, or answer `{first_of_its_kind: <reason>}`"]
    out = []
    for n, e in enumerate(v, 1):
        if not isinstance(e, dict):
            out.append(f"entry {n} is not a mapping — write it `{{name: <product>, for: {' | '.join(REFERENCE_FOR)}}}`"); continue
        if "first_of_its_kind" in e:
            r = e["first_of_its_kind"]
            if set(e) != {"first_of_its_kind"}:
                out.append(f"entry {n}: «first of its kind» stands alone — `{{first_of_its_kind: <reason>}}`, no other field")
            elif not isinstance(r, str) or not r.strip():
                out.append(f"entry {n}: «first of its kind» needs its reason — say why no product on the market compares")
            continue
        extra = sorted(set(map(str, e)) - set(REFERENCE_FIELDS))
        if extra:
            out.append(f"entry {n}: {', '.join(f'`{clean(x, 60)}`' for x in extra)} is not a field ({', '.join(REFERENCE_FIELDS[:4])})")
        if not isinstance(e.get("name"), str) or not e["name"].strip():
            out.append(f"entry {n}: the product's name is blank — name the product on the market")
        elif not _one_line(e["name"]) or re.search(r"https?://", e["name"], re.I):
            out.append(f"entry {n}: the name is one line of at most {REFERENCE_TEXT_MAX} characters, no address — the address goes in `link`")
        if e.get("for") not in REFERENCE_FOR:
            out.append(f"entry {n}: `for` = `{clean(canon(e.get('for')), 60)}` is not one of {' | '.join(REFERENCE_FOR)}")
        feat = e.get("feature")
        if e.get("for") == "feature" and (not isinstance(feat, str) or not feat.strip()):
            out.append(f"entry {n}: `for: feature` names the feature it is a reference for — `feature: <the feature>`")
        elif e.get("for") == "feature" and not _one_line(feat):
            out.append(f"entry {n}: the feature is one line of at most {REFERENCE_TEXT_MAX} characters")
        if e.get("for") != "feature" and "feature" in e:
            out.append(f"entry {n}: `feature` goes with `for: feature` only")
        link = e.get("link")
        if link is not None and not (isinstance(link, str) and re.fullmatch(r"https?://[^\s<>\"'`]+", link.strip())):
            out.append(f"entry {n}: the link is not a public http(s) address")
        elif link is not None and "@" in _netloc(link):
            out.append(f"entry {n}: the link carries a user or a password — point at the product's public page, never with a credential")
    return out


def _answered(key: str, ans: dict) -> bool:
    return any(v is not None for k, v in ans.items() if k == key or k.startswith(key + "."))


def _offered_for(spec: dict, ans: dict) -> list[str] | None:
    """The literals a key admits for this answer set: its options, or its parent's row of options_by (None: free / parent unanswered)."""
    if isinstance(spec.get("options"), list):
        return [canon(x) for x in spec["options"]]
    ob = spec.get("options_by")
    if isinstance(ob, dict) and isinstance(ob.get("values"), dict):
        row = ob["values"].get(canon(ans.get(ob.get("key"))) if ans.get(ob.get("key")) is not None else None)
        return [canon(x) for x in row] if isinstance(row, list) else None
    return None


def _check_answers(reg: dict, ans: dict):
    """An answer outside its key's options is a fault naming the key — never a silent skip."""
    dec = decided(reg, ans)
    for k, v in matched(reg, ans)[0].items():
        if ans.get(k) is not None and canon(ans[k]) != canon(v):
            raise GateFault(f"the answer `{k}` = `{canon(ans[k])}` contradicts `{_derived(reg)[k]['matches']['key']}`, which selects `{canon(v)}` — the key is derived, never answered")
    for k, spec in _specs(reg).items():
        v = ans.get(k)
        if spec.get("free") == "references":
            nested = any(x.startswith(k + ".") and ans[x] is not None for x in ans)
            problems = (["is a mapping, not a list — write each product as a list entry `- {name: <product>, for: …}`"] if nested else []) \
                + _reference_problems(v)
            if problems:
                raise GateFault(f"the answer `{k}` — " + "; ".join(problems))
            continue
        if k in dec:
            if v is not None and canon(v) != canon(dec[k]):
                db = spec["decided_by"]
                raise GateFault(f"the answer `{k}` = `{canon(v)}` contradicts `{db['key']}` = `{canon(ans.get(db['key']))}`, which decides "
                                f"`{canon(dec[k])}` — the key is derived, never answered; clear it or answer `{db['key']}` again")
            continue
        offered = _offered_for(spec, ans)
        known = _known(spec) if spec.get("open") is True else None   # EVOL-131: an open list admits a name it does not know
        for x in (v if isinstance(v, list) else [v]) if v is not None and known is not None else []:
            if not canon(x).strip():
                raise GateFault(f"the answer `{k}` is blank — name the tool you use" + (f", or answer from its list ({' | '.join(offered)})" if offered else ""))
            near = None if canon(x) in known | {"None"} else next((n for n in sorted(known | {"None"}) if n.lower() == canon(x).strip().lower()), None)
            if near:
                raise GateFault(f"the answer `{k}` = `{canon(x)}` — did you mean `{near}`? Answer it with the registry's spelling")
        if v is None or offered is None:
            continue
        for x in (v if isinstance(v, list) else [v]):
            if canon(x) in offered or (known is not None and canon(x) not in known):
                continue
            if known is not None and isinstance(spec.get("options_by"), dict):
                parent = spec["options_by"]["key"]
                raise GateFault(f"the answer `{k}` = `{canon(x)}` belongs to another `{parent}` — under `{parent}` = `{canon(ans.get(parent))}` "
                                f"the list is {' | '.join(offered)}; answer it again, or name the tool you use if it is none of them")
            raise GateFault(f"the answer `{k}` = `{canon(x)}` is not one of its options ({' | '.join(offered)}) — "
                            f"answer it again from {REGISTRY}, never a literal of your own")


def _owed(reg: dict, q: dict, ans: dict) -> bool:
    """A question is owed when its `when` holds — or when it reads an unmodelled answer (EVOL-131) and some listed literal of
    that key would make it hold: the answer cannot say whether the question applies, so it is asked (`None` is an answer)."""
    w = q.get("when")
    if not isinstance(w, str) or evaluate(parse(w), ans):
        return True
    specs = _specs(reg)
    for u in {x["key"] for x in _unmodelled(reg, ans)}:
        if any(evaluate(parse(w), {**ans, u: lit}) for lit in _offered(specs[u]) or []):
            return True
    return False


def _unmodelled(reg: dict, ans: dict) -> list[dict]:
    """EVOL-131 — every answered open key whose answer is none of its literals: {key, answer, owes} in registry order;
    owes = the config pointers the key's shipped rows set (the contract a covered literal fills). `None` names no tool."""
    out = []
    for k, spec in _specs(reg).items():
        v = ans.get(k)
        if spec.get("open") is not True or v is None:
            continue
        known = _known(spec)
        rows = spec.get("configures") if isinstance(spec.get("configures"), dict) else {}
        owes = sorted({p for r in rows.values() if isinstance(r, dict) for p in r})
        out += [{"key": k, "answer": canon(x), "owes": owes} for x in (v if isinstance(v, list) else [v]) if _has_value(canon(x)) and canon(x) not in known]
    return out


def _declared(ans: dict, ptr: str):
    """The value declared in the answers under a config pointer: the key itself, or its flattened children rebuilt; None when absent."""
    if ans.get(ptr) is not None:
        return ans[ptr] if _has_value(ans[ptr]) and (not isinstance(ans[ptr], str) or ans[ptr].strip()) else None
    tree: dict = {}
    for k, v in sorted(ans.items()):
        if v is None or not k.startswith(ptr + "."):
            continue
        *parts, leaf = k[len(ptr) + 1:].split(".")
        node = tree
        for part in parts:
            node = node.setdefault(part, {})
            if not isinstance(node, dict):
                break
        else:
            node[leaf] = v
    return tree or None


def _built(reg: dict, ans: dict) -> tuple[list[tuple[str, dict]], list[str]]:
    """EVOL-131 — the declared rows of the unmodelled answers ([(where, {pointer: value})], merged like an option's row) and
    what is still owed: an owed pointer undeclared, declared out of a shipped row's shape (V12) or of another kind, or a
    dict pointer missing a name every shipped row sets, two rows or more (the backend's `tests` and `sca` gates, an adapter's `rollback`)."""
    rows, owed, specs, seen = [], [], _specs(reg), set()
    for u in _unmodelled(reg, ans):
        where = f"`{u['key']}` = `{u['answer']}`"
        shipped = [r for r in specs[u["key"]]["configures"].values() if isinstance(r, dict)] if u["owes"] else []
        for ptr in u["owes"]:
            val = _declared(ans, ptr)
            if val is None:
                owed.append(f"{where} — declare `{ptr}`"); continue
            vals = [r.get(ptr) for r in shipped]
            common = (set.intersection(*({n for n, x in v.items() if x is not None} for v in vals))   # a name a shipped row leaves null is optional
                      if len(vals) > 1 and all(isinstance(v, dict) for v in vals) else set())   # one row names one tool's own
            if isinstance(val, dict):
                owed += [f"{where} — declare `{ptr}.{n}`" for n in sorted(common - set(val))]
            if ptr in seen:
                continue   # one declaration answers every entry that owes the pointer: it lands once
            seen.add(ptr)
            bad = [f.split(" · ", 1)[-1] for f in _gate_rows(f"{where} (declared)", {ptr: val})]
            kinds = {type(r[ptr]).__name__ for r in shipped if r.get(ptr) is not None}
            if not bad and kinds and type(val).__name__ not in kinds:
                bad = [f"{where} (declared): `{ptr}` is a {type(val).__name__}, a shipped row's is a {' or '.join(sorted(kinds))}"]
            if bad:
                owed += bad
            else:
                rows.append((f"{u['key']} = {u['answer']} (declared)", {ptr: val}))
    return rows, owed


def _free_text(reg: dict, ans: dict) -> list[str]:
    """EVOL-131 — the owed options_by keys whose parent's answer has no row: asked as free text, never from another row."""
    dec, out = decided(reg, ans), []
    for q in _questions(reg):
        if not _owed(reg, q, ans):
            continue
        for k, s in ((q.get("keys") or {}) if isinstance(q.get("keys"), dict) else {}).items():
            ob = s.get("options_by") if isinstance(s, dict) else None
            if not isinstance(ob, dict) or not isinstance(ob.get("values"), dict) or k in dec or ans.get(ob.get("key")) is None:
                continue
            if not isinstance(ob["values"].get(canon(ans[ob["key"]])), list):
                out.append(k)
    return out


def _pointer(doc, ptr: str) -> bool:
    for part in ptr.split("/")[1:]:
        part = part.replace("~1", "/").replace("~0", "~")
        if isinstance(doc, dict) and part in doc:
            doc = doc[part]
        elif isinstance(doc, list) and part.isdigit() and int(part) < len(doc):
            doc = doc[int(part)]
        else:
            return False
    return True


def _detected(repo: Path, detect: str) -> bool:
    """`<file>#<pointer>` holds when the file parses and the pointer resolves (a .md file: its frontmatter)."""
    m = DETECT.match(detect)
    if not m:
        raise GateFault(f"the migration detect `{detect}` is not `always` or `<project file>#/<JSON pointer>` — run `gate.py discovery`")
    p = repo / m.group(1)
    if not p.is_file():
        return False
    try:
        doc = read_frontmatter(p) if p.suffix == ".md" else json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    return _pointer(doc, m.group(2))


def project_version(repo: Path) -> tuple:
    """The project's framework version (its manifest snapshot); absent or unreadable reads as 0.0.0 (upgrade Step 0)."""
    try:
        v = json.loads((repo / PROJECT_MANIFEST).read_text(encoding="utf-8")).get("framework_version")
    except (OSError, ValueError, AttributeError):
        v = None
    return _semver(v) or (0, 0, 0)


def resolve(repo: Path, ans: dict, project: bool = False) -> dict:
    reg = load_registry(repo)
    manifest = load_manifest(repo)
    templates = manifest.get("templates")
    if not isinstance(templates, dict) or not templates:
        raise GateFault(f"the governance manifest {MANIFEST} carries no `templates` entries — nothing to select from")
    for where, c in _conditions(repo, reg, manifest):   # fail-closed: a condition the registry does not hold faults, never skips
        try:
            problems = check(parse(c), reg)
        except GateFault as e:
            raise GateFault(f"{where}: {e}") from None
        if problems:
            raise GateFault(f"{where}: `{c}` does not hold to the registry: " + "; ".join(problems))
    _check_answers(reg, ans)
    derived_answers = {k: v for k, v in decided(reg, ans).items() if ans.get(k) is None}
    ans = {**ans, **derived_answers}
    qs = sorted(enumerate(_questions(reg)), key=lambda iq: (iq[1].get("tier") if isinstance(iq[1].get("tier"), int) else 99, iq[0]))
    pending = []
    for _, q in qs:
        if not _owed(reg, q, ans):
            continue
        if not any(_answered(k, ans) and not _carried_only(ans.get(k)) for k in (q.get("keys") or {})):   # asked = some key holds an answer (null = not yet asked; a carried answer is shown, then asked);
            pending.append(q.get("id"))                                 # a sibling left null on purpose (Q14 path, Q29.1 dir) is part of it
    landing, skipped = [], []
    for k, e in templates.items():
        if not isinstance(e, dict):
            continue
        c = e.get("stack_conditional")
        (landing if not c or evaluate(parse(c), ans) else skipped).append(k)
    since = {q.get("id"): q.get("since") for q in _questions(reg)}
    fills = {t: ans.get(k) for k, s in _specs(reg).items() for t in (s.get("fills") or [])}
    fills.update({t: ans[k] for k, s in _derived(reg).items() if isinstance(s, dict) and ans.get(k) is not None
                  for t in (s.get("fills") or [])})   # a decided value fills its token too (EVOL-079: TRACKER_ADAPTER)
    out = {"pending": pending, "pending_since": {q: since.get(q) for q in pending}, "landing": landing, "skipped": skipped,
           "placeholders": fills, "derived_answers": derived_answers, "configures": configures(reg, ans), "warnings": matched(reg, ans)[1]}
    out["defect_classes"] = defect_classes(repo, reg, out["configures"], ans, pending, project)
    specs = _specs(reg)
    out["unmodelled"] = [{**u, "templates": [t for t in skipped if isinstance(templates[t].get("stack_conditional"), str)   # a slot a listed literal would fill
                                             and any(evaluate(parse(templates[t]["stack_conditional"]), {**ans, u["key"]: lit}) for lit in _offered(specs[u["key"]]) or [])]}
                         for u in _unmodelled(reg, ans)]
    out["free_text"] = _free_text(reg, ans)
    out["carried"] = [{"key": k, "from": s["carries"]["from"], "entries": ans[k]} for k, s in specs.items()
                      if isinstance(s.get("carries"), dict) and isinstance(ans.get(k), list) and any(isinstance(e, dict) and e.get("carried_from") for e in ans[k])]
    lacking, owed = _unverified_parts(reg, ans), _built(reg, ans)[1]
    stops = ([STOP.format(parts="; ".join(lacking))] if lacking else []) + ([STOP_BUILD.format(owed="; ".join(owed))] if owed else [])
    if stops:
        out["stop"] = " · ".join(stops)
    if project:
        ver = project_version(repo)
        target = lambda k: templates[k].get("target") if inside(k) and inside(templates[k].get("target")) else None
        out["project_version"] = ".".join(map(str, ver))
        out["migrations_owed"] = [{"id": m.get("id"), "since": m.get("since"), "apply": m.get("apply")} for m in (reg.get("migrations") or [])
                                  if isinstance(m, dict) and (m.get("detect") == "always"   # every upgrade, whatever its since
                                  or (ver < (_semver(m.get("since")) or (0, 0, 0)) and not _detected(repo, str(m.get("detect")))))]
        out["templates_to_add"] = [k for k in landing if target(k) and not (repo / target(k)).exists()]
        out["templates_to_remove"] = [k for k in skipped if target(k) and (repo / target(k)).exists()]
        out["gates_upgrade"] = gates_upgrade(repo, out["configures"])
        # EVOL-136 — by owner: a framework-owned landed file that differs from its delivered template is refreshed by script;
        # a project-owned template that moved since the snapshot is listed, never written (a row carries a change to it);
        # the seams merge by key, add-only
        src = lambda k: repo / TEMPLATE_ROOT / k
        try:
            snap = json.loads((repo / PROJECT_MANIFEST).read_text(encoding="utf-8")).get("templates") or {}
        except (OSError, ValueError, AttributeError):
            snap = {}
        out["templates_to_refresh"] = [k for k in landing if templates[k].get("owner") == "framework" and target(k) and (repo / target(k)).is_file()
                                       and src(k).is_file() and (repo / target(k)).read_bytes() != src(k).read_bytes()]
        out["templates_moved"] = [{"key": k, "target": target(k), "from": snap[k].get("version"), "to": templates[k].get("version")} for k in landing
                                  if templates[k].get("owner") == "project" and isinstance(snap.get(k), dict)
                                  and (_semver(templates[k].get("version")) or (0, 0, 0)) > (_semver(snap[k].get("version")) or (0, 0, 0))]
        out["seams_upgrade"] = {t: {x: s[x] for x in ("added", "replaced", "unresolved")} for t, s in seams_upgrade(repo, fills).items()}
    out["configures"].pop("verification.gates.was", None)
    return out


def gates_upgrade(repo: Path, conf: dict) -> dict:
    """The project's verification.gates against the derived rows, field by field (EVOL-067, EVOL-116): a field it lacks is
    added; a value equal to a superseded template value (`was`) is replaced — dropped when the row no longer derives it;
    a value it changed is kept. Nothing else moves. {gates, added, replaced, kept}, each list `<gate>.<field>`."""
    derived, was = conf.get("verification.gates") or {}, conf.get("verification.gates.was") or {}
    q = repo / "config/quality.json"   # absent: no rows yet; present and unreadable: never read as «no rows» (it would drop the project's own)
    try:
        have = (((json.loads(q.read_text(encoding="utf-8")) if q.is_file() else {}).get("verification") or {}).get("gates")) or {}
    except (OSError, ValueError) as e:
        raise GateFault(f"config/quality.json cannot be read ({e}) — repair it, then run the upgrade again; its gate rows are never guessed")
    except AttributeError:
        raise GateFault("config/quality.json is not a JSON object — repair it, then run the upgrade again; its gate rows are never guessed") from None
    if not isinstance(have, dict):
        raise GateFault("config/quality.json → verification.gates is not a map of rows — repair it, then run the upgrade again; its gate rows are never guessed")
    gates, added, replaced, kept = {}, [], [], []
    for name in list(have) + [n for n in derived if n not in have]:
        mine, new, old = have.get(name), derived.get(name), was.get(name) or {}
        if not isinstance(mine, dict) or not isinstance(new, dict):
            gates[name] = mine if isinstance(mine, dict) else new
            if not isinstance(mine, dict):
                added.append(name)
            continue
        row = dict(mine)
        for f in list(dict.fromkeys(list(mine) + list(new))):
            if f == "reads":
                continue
            if f not in mine:
                row[f] = new[f]; added.append(f"{name}.{f}")
            elif mine[f] in (old.get(f) or []):
                if f in new:
                    row[f] = new[f]
                else:
                    row.pop(f)
                replaced.append(f"{name}.{f}")
            elif f in new and mine[f] != new[f]:
                kept.append(f"{name}.{f}")
        gates[name] = row
    return {"gates": gates, "added": added, "replaced": replaced, "kept": kept}


def inside(path) -> bool:
    """A manifest path stays inside its root: relative, no control character, no segment of dots or spaces alone (`..`,
    `.. ` — what a filesystem resolves upward) (EVOL-136 — one containment check: sync, the seams, the refresh)."""
    return isinstance(path, str) and bool(path) and not path.startswith(("/", "\\", "~")) and ":" not in path \
        and not any(ord(c) < 32 or ord(c) == 127 for c in path) \
        and not any(s not in ("", ".") and not s.strip(" .") for s in path.replace("\\", "/").split("/"))


UNRESOLVED = "\x00unresolved:"   # a token no answer fills: the key it sits in is listed, never written
HOOK_SCRIPT = re.compile(r"((?:\.claude/hooks|scripts)/[\w./-]+\.(?:sh|py))(?:\s+([a-z][\w-]*))?")
SEAM_WAS_MATCHERS = {("PreToolUse", ".claude/hooks/check-completion-gate.sh"): ("Write",)}   # #171: the one superseded wiring a seam replaces


def _hook_key(cmd: str) -> str:
    """A framework hook is known by the script it runs (`gate.py` with its subcommand), never by its command form."""
    m = HOOK_SCRIPT.search(cmd or "")
    if not m:
        return (cmd or "").strip()
    return m.group(1) + (f" {m.group(2)}" if m.group(1).endswith("gate.py") and m.group(2) else "")


def _render_seam(text: str, fills: dict) -> dict:
    """A seam template with its placeholders rendered from the answers; a token no answer fills becomes a marker."""
    def val(tok):
        return json.dumps(fills[tok]) if fills.get(tok) is not None else json.dumps(UNRESOLVED + tok)
    text = re.sub(r'"\{\{([A-Z0-9_]+)\}\}"|\{\{([A-Z0-9_]+)\}\}', lambda mo: val(mo.group(1) or mo.group(2)), text)   # one pass: a value is never re-read
    return json.loads(text)


def _unresolved(v) -> list[str]:
    if isinstance(v, str):
        return [v[len(UNRESOLVED):]] if v.startswith(UNRESOLVED) else []
    if isinstance(v, dict):
        return [t for x in v.values() for t in _unresolved(x)]
    if isinstance(v, list):
        return [t for x in v for t in _unresolved(x)]
    return []


def _merge_keys(mine: dict, tpl: dict, at: str, added: list, unresolved: list) -> None:
    """Add what is absent, key by key; a present value is kept, a list is a leaf; a value an answer cannot fill is listed."""
    for k, v in tpl.items():
        here = f"{at}/{k}"
        if k not in mine:
            toks = _unresolved(v)
            if toks:
                unresolved.append(f"{here} ({', '.join(sorted(set(toks)))})")
            else:
                mine[k] = v; added.append(here)
        elif isinstance(mine[k], dict) and isinstance(v, dict):
            _merge_keys(mine[k], v, here, added, unresolved)


def _merge_hooks(mine: dict, tpl: dict, added: list, replaced: list) -> None:
    """`hooks`, keyed: an absent event lands whole; a framework hook is known by (matcher, script) — one wired under another
    matcher only is added under the template's (one script may guard several matchers); the bare command form and a declared
    superseded matcher are replaced; the project's own entries are kept, only an entry a move emptied is dropped."""
    for ev, entries in tpl.items():
        if not isinstance(mine.get(ev), list):
            if ev not in mine:
                mine[ev] = entries; added.append(f"/hooks/{ev}")
            continue
        for te in entries:
            for th in te.get("hooks", []):
                key, cmd = _hook_key(th.get("command")), th.get("command") or ""
                bare = cmd.split("&& ", 1)[1].strip() if "&& " in cmd else None
                where = [(e, h) for e in mine[ev] if isinstance(e, dict) and isinstance(e.get("hooks"), list) for h in e["hooks"]
                         if isinstance(h, dict) and _hook_key(h.get("command")) == key]
                for e, h in where:
                    if bare and (h.get("command") or "").strip() == bare:
                        h["command"] = cmd; replaced.append(f"/hooks/{ev}/{key}: command")
                old = SEAM_WAS_MATCHERS.get((ev, key), ())
                moved = [(e, h) for e, h in where if e.get("matcher") in old and e.get("matcher") != te.get("matcher")]
                for e, h in moved:
                    e["hooks"].remove(h)
                    replaced.append(f"/hooks/{ev}/{key}: matcher {e.get('matcher')} -> {te.get('matcher')}")
                emptied = [e for e, _ in moved if not e["hooks"]]
                mine[ev][:] = [e for e in mine[ev] if not any(e is x for x in emptied)]
                if any(e.get("matcher") == te.get("matcher") and not any(h is y for _, y in moved) for e, h in where):
                    continue
                home = next((e for e in mine[ev] if isinstance(e, dict) and e.get("matcher") == te.get("matcher")), None)
                if home is None:
                    home = {k: v for k, v in te.items() if k != "hooks"} | {"hooks": []}
                    mine[ev].append(home)
                home["hooks"].append(th)
                if not moved:
                    added.append(f"/hooks/{ev}/{key}")


def seams_upgrade(repo: Path, fills: dict) -> dict:
    """The seams (EVOL-136): every template the manifest marks `owner: seam`, merged into the project's file by key, add-only —
    an absent key lands with its placeholders resolved, an existing value is kept, a list is a leaf; `hooks` is keyed by the
    script each runs. Per target {merged, added, replaced, unresolved}; a second run adds nothing. An unreadable project file
    is a fault: it is never read as empty."""
    out = {}
    for k, e in (load_manifest(repo).get("templates") or {}).items():
        if not isinstance(e, dict) or e.get("owner") != "seam" or not isinstance(e.get("target"), str):
            continue
        if not inside(k) or not inside(e["target"]):
            raise GateFault(f"the seam {k} → {e['target']}: a path outside the project — the delivered manifest is damaged; run factory-sync.sh")
        src, dst = repo / TEMPLATE_ROOT / k, repo / e["target"]
        try:
            tpl = _render_seam(src.read_text(encoding="utf-8"), fills or {})
        except (OSError, ValueError) as ex:
            raise GateFault(f"the seam template {TEMPLATE_ROOT}{k} cannot be read ({ex}) — run factory-sync.sh") from None
        try:
            mine = json.loads(dst.read_text(encoding="utf-8")) if dst.is_file() else {}
        except (OSError, ValueError) as ex:
            raise GateFault(f"{e['target']} cannot be read ({ex}) — repair it, then run the upgrade again; a seam is never read as empty") from None
        if not isinstance(mine, dict) or not isinstance(tpl, dict):
            raise GateFault(f"{e['target']} is not a JSON object — repair it, then run the upgrade again")
        added, replaced, unresolved = [], [], []
        hooks = tpl.pop("hooks", None)
        _merge_keys(mine, tpl, "", added, unresolved)
        if isinstance(hooks, dict):
            if not isinstance(mine.get("hooks"), dict):
                if "hooks" not in mine:
                    mine["hooks"] = hooks; added.append("/hooks")
            else:
                _merge_hooks(mine["hooks"], hooks, added, replaced)
        out[e["target"]] = {"merged": mine, "added": added, "replaced": replaced, "unresolved": unresolved}
    return out


def _tool_bound(reg: dict) -> dict[str, list[str]]:
    """Every class id an option's `configures` names (a tool-bound row: it lands only where its tool is), or a derived row
    with `when` names, → the keys that bind it."""
    out: dict[str, list[str]] = {}
    for k, s in _specs(reg).items():
        for rows in (s.get("configures") or {}).values() if isinstance(s.get("configures"), dict) else []:
            ids = rows.get(DC_POINTER) if isinstance(rows, dict) else None
            for i in (ids if isinstance(ids, list) else []):
                keys = out.setdefault(i, [])
                if k not in keys:
                    keys.append(k)
    for s in _derived(reg).values():   # a stack-bound derived row (EVOL-071): its classes bind to the keys its `when` reads
        rows = s.get("configures") if isinstance(s, dict) else None
        ids = rows.get(DC_POINTER) if isinstance(rows, dict) and isinstance(s.get("when"), str) else None
        for i in (ids if isinstance(ids, list) else []):
            keys = out.setdefault(i, [])
            for c in (c for conj in parse(s["when"]) for c in conj):
                if c["key"] not in keys:
                    keys.append(c["key"])
    return out


def defect_classes(repo: Path, reg: dict, conf: dict, ans: dict, pending: list, project: bool) -> dict:
    """`drop`: the tool-bound ids the answers rule out — an id whose key is unanswered while questions are pending is
    undecided and stays — any pending question, not only its own: a question whose `when` reads an unanswered key may
    still become owed. Against a project also `to_add`, `to_remove` (dropped rows it holds as the same class) and
    `collisions` (a template id it holds as another class, dropped ids excepted)."""
    from . import corpus
    picked = conf.get(DC_POINTER) or []
    drop = [i for i, keys in _tool_bound(reg).items()
            if i not in picked and not (pending and any(not _answered(k, ans) for k in keys))]
    out: dict = {"drop": drop}
    if not project:
        return out
    for rel in (TEMPLATE_CATALOG, TEMPLATE_CASES):
        if not (repo / rel).is_file():
            raise GateFault(f"the template defect catalog {rel} is missing — run factory-sync.sh to deliver the templates, then run again")
    tpl, tcases = corpus.catalog(repo, repo / TEMPLATE_CATALOG), corpus.cases(repo / TEMPLATE_CASES)
    mine = {d["id"]: d for d in corpus.catalog(repo, repo / PROJECT_CATALOG)["dcs"]}
    pcases = corpus.cases(repo / PROJECT_CASES)
    out.update(to_add=[], to_remove=[], collisions=[])
    for d in tpl["dcs"]:
        i, have = d["id"], mine.get(d["id"])
        if have is None:
            if i not in drop:
                out["to_add"].append(i)
        elif have["invariant"] == d["invariant"] or (i in pcases and pcases.get(i) == tcases.get(i)):
            if i in drop:
                out["to_remove"].append(i)
        elif i not in drop:
            out["collisions"].append({"id": i, "project": pcases.get(i) or have["invariant"], "framework": tcases.get(i) or d["invariant"]})
    return out


def _merge(into: dict, rows: dict, where: str):
    for ptr, v in rows.items():
        if isinstance(v, dict):
            have = into.setdefault(ptr, {})
            for name, row in v.items():
                if name in have:
                    raise GateFault(f"`{ptr}` → `{name}` is configured by two answered sources ({have[name]['_from'] if isinstance(have[name], dict) else '?'}, {where}) — one row, one source (registry {REGISTRY})")
                have[name] = {**row, "_from": where} if isinstance(row, dict) else row
        elif isinstance(v, list):
            into[ptr] = into.get(ptr, []) + [x for x in v if x not in into.get(ptr, [])]
        else:
            into[ptr] = v


def configures(reg: dict, ans: dict) -> dict:
    """The answered options' `configures` rows and every derived entry's, merged; the gate rows completed with reads."""
    out: dict = {}
    for k, s in _specs(reg).items():
        rows = s.get("configures") if isinstance(s.get("configures"), dict) else {}
        v = ans.get(k)
        if v is not None and isinstance(rows.get(canon(v)), dict):
            _merge(out, rows[canon(v)], f"{k} = {canon(v)}")
    for where, row in _built(reg, ans)[0]:   # EVOL-131: an unmodelled answer's declared rows, merged as its option's row would be
        _merge(out, row, where)
    for k, s in _derived(reg).items():
        if isinstance(s, dict) and isinstance(s.get("configures"), dict):
            if isinstance(s.get("when"), str) and not evaluate(parse(s["when"]), ans):
                continue   # a stack-bound derived row (EVOL-074): configured only when its condition holds
            _merge(out, s["configures"], f"derived {k}")
    surface = ans.get("surface.runtime_surface")
    reads = (list(surface) if isinstance(surface, list) else []) + [r for r in out.get("traceability.test_roots", []) if not (isinstance(surface, list) and r in surface)]
    thr = ans.get("quality.security_scan.sca_threshold")
    for name, row in out.get("verification.gates", {}).items():
        row.pop("_from", None)
        was = row.pop("was", None)
        if was:
            out.setdefault("verification.gates.was", {})[name] = was   # read by the upgrade merge only; never lands in the project
        if isinstance(row.get("command"), str) and thr is not None:
            row["command"] = row["command"].replace("{sca_threshold}", canon(thr))
        row["reads"] = reads
    for ptr, v in out.items():
        if isinstance(v, dict):
            for row in v.values():
                if isinstance(row, dict):
                    row.pop("_from", None)
    return out


def checked(repo: Path, cond: str) -> list[list[dict]]:
    """A condition parsed and held to the registry, before any answer is read; GateFault otherwise."""
    ast = parse(cond)
    problems = check(ast, load_registry(repo))
    if problems:
        raise GateFault(f"the condition `{cond}` does not hold to the registry: " + "; ".join(problems))
    return ast


def eval_condition(repo: Path, cond: str, ans: dict) -> bool:
    return evaluate(checked(repo, cond), with_decided(load_registry(repo), ans))


def _unverified_parts(reg: dict, ans: dict) -> list[str]:
    """Each answered stack part (not `None`) with none of its verifying gates — from its own registry rows or the rows
    declared at discovery (docs/setup.md → verification.gates, flattened `verification.gates.<gate>.<field>`)."""
    declared = {k.split(".")[2] for k, v in ans.items() if k.startswith("verification.gates.") and len(k.split(".")) > 2 and v is not None}
    specs, out = _specs(reg), []
    for k, need in LOOP_PARTS.items():
        v = ans.get(k)
        if v is None or canon(v) == "None":
            continue
        rows = (specs.get(k) or {}).get("configures") or {}
        own = set((rows.get(canon(v)) or {}).get("verification.gates") or {}) if isinstance(rows, dict) else set()
        if not set(need) & (own | declared):
            out.append(f"{k} = {canon(v)} (no {' or '.join(f'`{g}`' for g in need)} gate)")
    return out


def render_resolve(r: dict) -> str:
    pend = ", ".join(f"{q} (since {r['pending_since'].get(q)})" for q in r["pending"])
    lines = [f"discovery: {len(r['pending'])} pending question(s)" + (f": {pend}" if r["pending"] else " — every question that applies is answered")]
    if r.get("stop"):
        lines.append(f"  stop: {r['stop']}")
    for u in r.get("unmodelled") or []:
        lines.append(f"  unmodelled — `{u['key']}` = `{clean(u['answer'], 200)}`: build it to the same contract; owes "
                     + (", ".join(f"`{p}`" for p in u["owes"]) or "no config pointer")
                     + (f"; templates to mirror in its idiom: {', '.join(u['templates'])}" if u["templates"] else ""))
    for c in r.get("carried") or []:
        lines.append(f"  carried — `{c['from']}` is now read under `{c['key']}`, verbatim: write it there, remove `{c['from']}`, then ask the question with it shown")
    if r.get("free_text"):
        lines.append("  free text — the parent's answer has no list, ask it as free text: " + ", ".join(r["free_text"]))
    lines += [f"  WARN: {w}" for w in r.get("warnings") or []]
    if r.get("derived_answers"):
        lines.append("  derived — an earlier answer decides them, never asked: " + ", ".join(f"{k} = {canon(v)}" for k, v in r["derived_answers"].items()))
    empty = sorted(t for t, v in r.get("placeholders", {}).items() if v is None)
    lines.append(f"  placeholders from answers: {len(r.get('placeholders', {})) - len(empty)} filled, {len(empty)} unanswered" + (f" ({', '.join(empty)})" if empty else ""))
    dc = r.get("defect_classes") or {}
    lines.append(f"  defect classes dropped — the answers select no tool they bind to ({len(dc.get('drop', []))})" + (f": {', '.join(dc['drop'])}" if dc.get("drop") else ""))
    if "migrations_owed" in r:
        lines.append(f"  project at {r['project_version']} — migrations owed ({len(r['migrations_owed'])}):")
        lines += [f"    > {m['id']} (since {m['since']}) — apply: {m['apply']}" for m in r["migrations_owed"]]
        lines += [f"  templates to add ({len(r['templates_to_add'])}):"] + [f"    + {k}" for k in r["templates_to_add"]]
        lines += [f"  templates to remove — offer, never silently ({len(r['templates_to_remove'])}):"] + [f"    - {k}" for k in r["templates_to_remove"]]
        gu = r.get("gates_upgrade") or {}
        for label, k in (("added", "added"), ("replaced — a superseded template value", "replaced"), ("kept — the project changed it", "kept")):
            lines += [f"  verification.gates {label} ({len(gu.get(k, []))})" + (f": {', '.join(gu[k])}" if gu.get(k) else "")]
        if "to_add" in dc:
            lines += [f"  defect classes to add ({len(dc['to_add'])}):"] + [f"    + {i}" for i in dc["to_add"]]
            lines += [f"  defect classes to remove — offer, never silently ({len(dc['to_remove'])}):"] + [f"    - {i}" for i in dc["to_remove"]]
            lines += [f"  defect class collisions — one RDR each ({len(dc['collisions'])}):"] + [f"    ! {c['id']}: project «{c['project']}» ≠ framework «{c['framework']}»" for c in dc["collisions"]]
        return "\n".join(lines)
    lines.append(f"  templates landing ({len(r['landing'])}):")
    lines += [f"    + {k}" for k in r["landing"]]
    lines.append(f"  templates skipped ({len(r['skipped'])}):")
    lines += [f"    - {k}" for k in r["skipped"]]
    return "\n".join(lines)


# ─── validator ───────────────────────────────────────────────────────────────────

def _semver(v) -> tuple | None:
    m = SEMVER.match(str(v or ""))
    return tuple(int(x) for x in m.groups()) if m else None


def _v1(reg: dict, fw: tuple | None) -> list[str]:
    out, ids, keys = [], {}, {}
    for top in reg:
        if top not in TOP_FIELDS and not top.startswith(("_", "$")):
            out.append(f"V1 · top-level `{top}` is not a registry field ({', '.join(TOP_FIELDS)})")
    for n, q in enumerate(reg.get("questions") or []):
        if not isinstance(q, dict):
            out.append(f"V1 · question #{n + 1} is not an object"); continue
        qid = q.get("id")
        where = f"question `{qid}`" if qid else f"question #{n + 1}"
        if not isinstance(qid, str) or not QID.match(qid):
            out.append(f"V1 · {where}: id `{qid}` is not `Q<number>` (as its `#### Q…` heading)")
        elif qid in ids:
            out.append(f"V1 · `{qid}` is declared twice")
        ids.setdefault(qid, n)
        for f in q:
            if f not in ("id", "tier", "since", "when", "keys"):
                out.append(f"V1 · {where}: `{f}` is not a question field (id, tier, since, when, keys)")
        if q.get("tier") not in TIERS or isinstance(q.get("tier"), bool):
            out.append(f"V1 · {where}: tier {q.get('tier')} is not one of {', '.join(map(str, TIERS))}")
        sv = _semver(q.get("since"))
        if sv is None:
            out.append(f"V1 · {where}: since `{q.get('since')}` is not a version (x.y.z)")
        elif fw is not None and sv > fw:
            out.append(f"V1 · {where}: since {q.get('since')} is above framework_version {'.'.join(map(str, fw))}")
        if "when" in q and (not isinstance(q["when"], str) or not q["when"].strip()):
            out.append(f"V1 · {where}: `when` is not a condition")
        if not isinstance(q.get("keys"), dict) or not q["keys"]:
            out.append(f"V1 · {where}: no `keys`"); continue
        for k, s in q["keys"].items():
            if not re.fullmatch(r"[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)*", k):
                out.append(f"V1 · {where}: key `{k}` is not a dotted lower-case key")
            if k in keys:
                out.append(f"V1 · key `{k}` is declared twice ({keys[k]}, {qid})")
            keys.setdefault(k, qid)
            if not isinstance(s, dict):
                out.append(f"V1 · `{k}`: its spec is not an object"); continue
            kinds = [x for x in SPEC_KINDS if x in s]
            if len(kinds) != 1:
                out.append(f"V1 · `{k}`: a spec carries exactly one of options | options_by | free (it carries {', '.join(kinds) or 'none'})")
            for f in s:
                if f not in SPEC_KINDS + ("record_only", "suggestions", "fills", "configures", "decided_by", "open", "carries"):
                    out.append(f"V1 · `{k}`: `{f}` is not a key-spec field (options, options_by, free, record_only, suggestions, fills, configures, decided_by, open, carries)")
            if "carries" in s:
                c = s["carries"]
                if s.get("free") != "references" or not isinstance(c, dict) or set(c) != {"from", "for"} \
                        or not isinstance(c.get("from"), str) or not re.fullmatch(r"[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)*", c["from"]) \
                        or c.get("for") not in REFERENCE_FOR:
                    out.append(f"V1 · `{k}`: carries is {{from: <the retired dotted key>, for: {' | '.join(REFERENCE_FOR)}}}, on a `free: references` key only (EVOL-132)")
            listed = "options" in s or "options_by" in s
            if listed != isinstance(s.get("open"), bool):
                out.append(f"V1 · `{k}`: open is true | false on every options / options_by key, and on no other — "
                           f"true for a market list (a tool the user may already use), false for framework vocabulary (EVOL-131)")
            if s.get("open") is False and any(o.lower().startswith("other") for o in _offered(s) or []):
                out.append(f"V1 · `{k}`: `Other` on a vocabulary list — only an open list (open: true) offers another answer")
            if "suggestions" in s and (s.get("free") != "text" or not isinstance(s["suggestions"], list) or not s["suggestions"]
                                       or len({canon(x) for x in s["suggestions"]}) != len(s["suggestions"])):
                out.append(f"V1 · `{k}`: suggestions is a non-empty list of distinct literals on a `free: text` key only")
            if "record_only" in s and (not isinstance(s["record_only"], str) or not s["record_only"].strip()):
                out.append(f"V1 · `{k}`: record_only needs its reason")
            if "options" in s and (not isinstance(s["options"], list) or not s["options"] or len({canon(x) for x in s["options"]}) != len(s["options"])):
                out.append(f"V1 · `{k}`: options is not a non-empty list of distinct literals")
            if "free" in s and s["free"] not in FREE_KINDS:
                out.append(f"V1 · `{k}`: free kind `{s['free']}` is not one of {', '.join(FREE_KINDS)}")
    specs = _specs(reg)
    for k, s in specs.items():
        c = s.get("carries")
        if isinstance(c, dict) and isinstance(c.get("from"), str) and (c["from"] in specs or c["from"] in (reg.get("derived") or {})):
            out.append(f"V1 · `{k}`: carries `{c['from']}`, which the registry still asks or derives — two homes for one answer; retire the old key")
    for k, s in specs.items():
        ob = s.get("options_by")
        if "options_by" not in s:
            continue
        if not isinstance(ob, dict) or not isinstance(ob.get("values"), dict) or not ob.get("key"):
            out.append(f"V1 · `{k}`: options_by is {{key, values: {{<parent literal>: [...]}}}}"); continue
        parent = specs.get(ob["key"])
        offered = _offered(parent) if parent and "options" in parent else None
        if offered is None:
            out.append(f"V1 · `{k}`: options_by names `{ob['key']}`, which is not a registry key with options"); continue
        for lit, vals in ob["values"].items():
            if lit not in offered:
                out.append(f"V1 · `{k}`: options_by literal `{lit}` is not one of `{ob['key']}`'s options ({' | '.join(offered)})")
            if not isinstance(vals, list) or not vals:
                out.append(f"V1 · `{k}`: options_by `{lit}` is not a non-empty list")
    for k, s in specs.items():
        if "decided_by" not in s:
            continue
        db = s["decided_by"]
        if not isinstance(db, dict) or set(db) != {"key", "values"} or not isinstance(db.get("values"), dict) or not db["values"] \
                or not all(isinstance(v, str) and v.strip() for v in db["values"].values()):
            out.append(f"V1 · `{k}`: decided_by is {{key, values: {{<parent literal>: \"<the value it decides>\"}}}}"); continue
        parent = specs.get(db["key"])
        offered = _offered(parent) if parent and db["key"] != k else None
        if offered is None:
            out.append(f"V1 · `{k}`: decided_by names `{db['key']}`, which is not another registry key with options"); continue
        out += [f"V1 · `{k}`: decided_by literal `{lit}` is not one of `{db['key']}`'s options ({' | '.join(offered)})"
                for lit in db["values"] if lit not in offered]
    d = reg.get("derived", {})
    if not isinstance(d, dict):
        out.append("V1 · `derived` is not an object")
    else:
        for k, s in d.items():
            if k in specs:
                out.append(f"V1 · `{k}` is both asked and derived")
            if not isinstance(s, dict) or not isinstance(s.get("from"), str) or not s["from"].strip() or set(s) - {"from", "fills", "configures", "when", "matches"} \
                    or ("when" in s and not (isinstance(s["when"], str) and "configures" in s)):
                out.append(f"V1 · derived `{k}`: the spec is {{from: \"<how earlier answers decide it>\", fills?: [TOKEN, …], configures?: {{<config pointer>: value}}, when?: \"<condition>\" (with configures), matches?: {{key, values, else, warn}}}}")
            m = s.get("matches") if isinstance(s, dict) else None
            if m is not None and not (isinstance(m, dict) and set(m) == {"key", "values", "else", "warn"} and specs.get(m["key"], {}).get("free") == "text"
                                      and isinstance(m["values"], dict) and m["values"] and all(isinstance(a, str) and a and isinstance(b, str) and b for a, b in m["values"].items())
                                      and isinstance(m["else"], str) and m["else"] and isinstance(m["warn"], str) and m["warn"].strip()):
                out.append(f"V1 · derived `{k}`: matches is {{key: <a free-text registry key>, values: {{<substring>: <value>}}, else: <value>, warn: \"<why, {{answer}}>\"}}")
    return out


def _v2(reg: dict) -> list[str]:
    out = []
    for k, s in _specs(reg).items():
        if isinstance(s.get("options"), list) and len(s["options"]) == 1:
            out.append(f"V2 · `{k}` offers one option ({canon(s['options'][0])}) — a decided value is derived, never asked: move it to `derived`")
        ob = s.get("options_by")
        if isinstance(ob, dict) and isinstance(ob.get("values"), dict):
            dec = (s.get("decided_by") or {}).get("values") if (s.get("decided_by") or {}).get("key") == ob.get("key") else None
            for lit, vals in ob["values"].items():
                if isinstance(vals, list) and len(vals) == 1 and not (isinstance(dec, dict) and dec.get(lit) == canon(vals[0])):   # decided already (EVOL-081)
                    out.append(f"V2 · `{k}` offers one option when `{ob.get('key')}` is `{lit}` ({canon(vals[0])}) — derive it, never ask it")
    return out


def _credential(key: str) -> bool:
    for seg in key.split("."):
        words = seg.lower().split("_")
        if CREDENTIAL_WORDS & set(words) or any(p in CREDENTIAL_PAIRS for p in zip(words, words[1:])):
            return True
    return False


def _v3(reg: dict) -> list[str]:
    return [f"V3 · `{k}` can carry a secret — its spec must be `free: vault_name` (the vault entry's name, never the value)"
            for k, s in _specs(reg).items() if _credential(k) and s.get("free") != "vault_name"]


def _consumer_files(repo: Path) -> list[str]:
    return [f for f in tracked_files(repo)
            if f.startswith(CONSUMER_ROOTS) and f not in NOT_CONSUMERS and not any(fnmatch.fnmatch(f, g) for g in NOT_CONSUMER_GLOBS)]


def _v4(repo: Path, reg: dict) -> list[str]:
    # a key whose `fills` names a token is read by the template that carries it (V10 holds the token to a template)
    owed = [k for k, s in _specs(reg).items() if not (isinstance(s.get("record_only"), str) and s["record_only"].strip()) and not s.get("fills")]
    if not owed:
        return []
    rx = re.compile(r"(?<![A-Za-z0-9_])(" + "|".join(re.escape(k) for k in sorted(owed, key=len, reverse=True)) + r")(?![A-Za-z0-9_])")
    seen = set()
    for rel in _consumer_files(repo):
        try:
            text = (repo / rel).read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        seen.update(rx.findall(text))
        # a shorter key inside a longer one (`a.b` within `a.b.c`) is found by its own scan
        for k in owed:
            if k not in seen and k in text and re.search(r"(?<![A-Za-z0-9_])" + re.escape(k) + r"(?![A-Za-z0-9_])", text):
                seen.add(k)
    return [f"V4 · `{k}` is persisted and nothing reads it (scripts, .claude instructions / skills / commands / hooks, templates, workflows, config) — add its reader or a `record_only` reason"
            for k in owed if k not in seen]


def _conditions(repo: Path, reg: dict, manifest: dict) -> list[tuple[str, str]]:
    out = [(f"registry {q.get('id')} when", q["when"]) for q in _questions(reg) if isinstance(q.get("when"), str)]
    out += [(f"registry derived {k} when", s["when"]) for k, s in _derived(reg).items() if isinstance(s, dict) and isinstance(s.get("when"), str)]
    for sect, entries in manifest.items():
        if isinstance(entries, dict):
            for k, e in entries.items():
                if isinstance(e, dict) and e.get("stack_conditional") is not None:
                    out.append((f"manifest {k}", e["stack_conditional"]))
    return out


def _v5(repo: Path, reg: dict, manifest: dict) -> list[str]:
    out = []
    conds = _conditions(repo, reg, manifest)
    p = repo / MATERIALIZATION
    if not p.is_file():
        out.append(f"V5 · {MATERIALIZATION} is absent — its `--eval` conditions cannot be checked")
    else:
        for n, line in enumerate(p.read_text(encoding="utf-8", errors="replace").splitlines(), 1):
            for m in re.finditer(r"discovery --eval(=|[ \t]+(\S)|[ \t]*$)?", line):
                if m.group(1) is None or m.group(2) == "`":
                    continue   # prose naming the flag, no condition after it
                if m.group(2) != "'":
                    out.append(f"V5 · {MATERIALIZATION}:{n}: write --eval conditions in single quotes, on the same line (a double-quoted, bare, "
                               f"`--eval=` or next-line condition is split by the shell or never checked)")
            for m in re.finditer(r"discovery --eval '([^']*)'", line):
                if not m.group(1).startswith("<"):   # a `<condition>` placeholder in usage prose is no condition
                    conds.append((f"{MATERIALIZATION}:{n}", m.group(1)))
    for where, c in conds:
        try:
            ast = parse(c)
        except GateFault as e:
            out.append(f"V5 · {where}: {e}"); continue
        out += [f"V5 · {where}: `{c}` — {p_}" for p_ in check(ast, reg)]
    return out


def _persist_keys(line: str) -> tuple[list[str], list[str], int]:
    """A `**Persist:**` line → (keys, wildcard prefixes, backticked token count). Dotted tokens anywhere; the first
    token also when it is one segment (`project_mode`); `.sub` reads under the line's first dotted key."""
    toks = re.findall(r"`([^`]+)`", line)
    keys, wild, base = [], [], None
    for i, t in enumerate(toks):
        t = t.strip()
        if re.fullmatch(r"[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)*\.\*", t):
            wild.append(t[:-2]); base = base or t[:-2]
        elif re.fullmatch(r"[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)+(?:\[\])?", t) or (i == 0 and re.fullmatch(r"[a-z][a-z0-9_]*(?:\[\])?", t)):
            k = t[:-2] if t.endswith("[]") else t
            keys.append(k)
            if base is None and "." in k:
                base = k.rsplit(".", 1)[0]
        elif base and re.fullmatch(r"\.[a-z0-9_]+(?:\[\])?", t):
            keys.append(base + (t[:-2] if t.endswith("[]") else t))
    return keys, wild, len(toks)


def _instruction(repo: Path) -> dict:
    """{qid: {keys, wild, toks, options, rows}} per `#### Q…` / `##### Q…` block (the parsing of test-discovery-literals)."""
    p = repo / INSTRUCTION
    if not p.is_file():
        raise GateFault(f"the discovery instruction {INSTRUCTION} is absent — V6 holds the registry to it")
    text = p.read_text(encoding="utf-8")
    out = {}
    for blk in re.split(r"\n(?=#{4,5} Q)", text):
        h = re.match(r"#{4,5} (Q[\d.]+[a-z]?)\b", blk)
        if not h:
            continue
        per = re.search(r"^- \*\*Persist[^*]*:\*\*[ \t]*(.+)$", blk, re.M)
        keys, wild, ntok = _persist_keys(per.group(1)) if per else ([], [], 0)
        opt = re.search(r"^- \*\*Options[^*]*:\*\*[ \t]*(.*)$", blk, re.M)
        rows = re.findall(r"^- ([^*`\n→]+?) → (.+)$", blk, re.M)   # Q10: per-parent rows
        def lits(row):
            return [re.sub(r"\s*\(.*$", "", o).strip().strip("`") for o in row.split("|")]
        def literal(opts):
            return opts and not any(not o or len(o) > 30 or re.search(r"[`:*]|^-", o) for o in opts)
        options = lits(opt.group(1)) if opt and opt.group(1).strip() else None
        options = sorted(set(options)) if options and literal(options) else None
        by = {lab.strip(): sorted(set(lits(r))) for lab, r in rows} if not opt and rows else None
        if by and not all(literal(v) for v in by.values()):
            by = None
        out[h.group(1)] = {"keys": keys, "wild": wild, "toks": ntok, "persist": bool(per), "options": options, "rows": by}
    return out


def _v6(repo: Path, reg: dict) -> list[str]:
    inst = _instruction(repo)
    out = []
    for q in _questions(reg):
        qid, qkeys = q.get("id"), list((q.get("keys") or {}).keys())
        if qid not in inst:
            out.append(f"V6 · registry question {qid} has no `#### {qid}` heading in the discovery instruction"); continue
        d = inst[qid]
        if not d["persist"]:
            out.append(f"V6 · {qid}: the instruction carries no `**Persist:**` line"); continue
        under = lambda k, p: k == p or k.startswith(p + ".")
        for k in d["keys"]:
            if not any(under(r, k) for r in qkeys):
                out.append(f"V6 · {qid}: the instruction persists `{k}`, the registry question does not")
        for w in d["wild"]:
            if not any(r.startswith(w + ".") for r in qkeys):
                out.append(f"V6 · {qid}: the instruction persists `{w}.*`, the registry question has no key under it")
        for r in qkeys:
            if not any(under(r, k) for k in d["keys"] + d["wild"]):
                out.append(f"V6 · {qid}: the registry persists `{r}`, the instruction's `**Persist:**` line does not")
        if d["toks"] != len(d["keys"]) + len(d["wild"]):
            continue   # values named beside the keys: a mapping, not one key's literals
        okeys = [k for k in qkeys if any(x in (q["keys"][k] or {}) for x in ("options", "options_by"))]
        if d["options"] is None and d["rows"] is None:
            continue   # options written as prose or bullets: nothing literal to compare
        if len(okeys) != 1:
            if len(qkeys) == 1:
                out.append(f"V6 · {qid}: the instruction offers literals, the registry declares `{qkeys[0]}` free")
            continue
        spec = q["keys"][okeys[0]]
        if d["rows"] is not None and isinstance(spec.get("options_by"), dict):
            vals = spec["options_by"].get("values") or {}
            for lab in sorted(set(d["rows"]) | set(vals)):
                want = sorted({canon(x) for x in vals.get(lab, [])})
                if d["rows"].get(lab) != want:
                    out.append(f"V6 · {qid}: when `{lab}`, the instruction offers {' | '.join(d['rows'].get(lab, [])) or 'nothing'}; the registry {' | '.join(want) or 'nothing'}")
            continue
        have = d["options"] if d["options"] is not None else sorted({x for v in d["rows"].values() for x in v})
        reg_opts = _offered(spec) or []
        if have != reg_opts:
            out.append(f"V6 · {qid}: the instruction offers {' | '.join(have)}; the registry `{okeys[0]}` offers {' | '.join(reg_opts)}")
    ids = {q.get("id") for q in _questions(reg)}
    out += [f"V6 · the instruction's `#### {h}` has no registry question" for h in inst if h not in ids]
    uop = re.search(r"^### Universal Option Protocol[^\n]*\n(.*?)(?=^#{1,3} |\Z)", (repo / INSTRUCTION).read_text(encoding="utf-8"), re.M | re.S)
    if not uop or "`open: true`" not in uop.group(1) or "`open: false`" not in uop.group(1):
        out.append("V6 · the instruction's Universal Option Protocol does not read the registry's `open` — it offers «Other» on an "
                   "`open: true` list and the literals only on an `open: false` one (EVOL-131)")
    return out


def _v7(repo: Path, reg: dict) -> list[str]:
    p = repo / TEMPLATE
    if not p.is_file():
        return [f"V7 · the setup template {TEMPLATE} is absent — the answer home has no slots"]
    slots = {k for k in flatten(read_frontmatter(p)) if k.split(".", 1)[0] not in NON_ANSWER_SLOTS}
    known = set(_specs(reg)) | set(_derived(reg))
    under = lambda a, b: a == b or a.startswith(b + ".")
    out = [f"V7 · `{k}` has no slot in the setup template frontmatter" for k in sorted(known) if not any(under(s, k) for s in slots)]
    out += [f"V7 · template slot `{s}` is not a registry or derived key (the non-answer slots are {', '.join(NON_ANSWER_SLOTS)})"
            for s in sorted(slots) if not any(under(s, k) for k in known)]
    return out


def _v9(reg: dict) -> list[str]:
    from . import corpus
    specs = _specs(reg)
    return [f"V9 · snapshot key `{k}` (corpus.STACK_KEYS) is not a registry key" for k in corpus.STACK_KEYS if k not in specs]


# ─── V8 · the consumer literals (ported from test-discovery-literals.sh, #143) ───

def _opts(reg: dict) -> dict:
    """The offered literals per key, and per question id when the question has one closed key."""
    out = {}
    for q in _questions(reg):
        closed = []
        for k, s in (q.get("keys") or {}).items():
            o = _offered(s) if isinstance(s, dict) else None
            if o is not None:
                out[k] = o; closed.append(k)
        if len(closed) == 1 and q.get("id"):
            out[q["id"]] = out[closed[0]]
    return out


def _v8(repo: Path, reg: dict, manifest: dict) -> list[str]:
    opts = _opts(reg)
    out = []

    def read(label, rel):
        p = repo / rel
        try:
            return p.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            out.append(f"V8 · {label}: {rel} is absent — nothing compared")
            return None

    def add(label, findings):
        out.extend(f"V8 · {label}: {f}" for f in findings[:12])

    entries = [(k, e) for _, sect in manifest.items() if isinstance(sect, dict) for k, e in sect.items() if isinstance(e, dict)]
    files = tracked_files(repo)

    # 1 · a literal compared in prose is offered
    lab = "conditional literals"
    cmp_ = re.compile(r"`?\b(Q\d+(?:\.\d+)?[a-z]?|[a-z_]+(?:\.[a-z_]+)+)`?\s*(==|!=)\s*"
                      r"(?:\"([^\"]+)\"|`([^`]+)`|'([^']+)'|((?!(?:AND|OR)\b)[\w.#+/-]+))")
    found = []
    for rel in files:
        if not rel.startswith((".claude/", ".context/templates/")) or "CHANGELOG" in rel or rel == REGISTRY \
                or any(fnmatch.fnmatch(rel, g) for g in NOT_CONSUMER_GLOBS):   # a test or a changelog is not a consumer
            continue
        try:
            text = (repo / rel).read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        for n, line in enumerate(text.splitlines(), 1):
            for m in cmp_.finditer(line):
                k, val = m.group(1), next(g for g in m.groups()[2:] if g is not None)
                if k in opts and val not in opts[k] + ["None", "null"]:
                    found.append(f"{rel}:{n}: `{k} {m.group(2)} {val}` — `{val}` is not offered ({' | '.join(opts[k])})")
    add(lab, found)

    # 2 · CI slugs: the materialisation's platform table names Q21's literals
    lab, q21 = "CI platform table", opts.get("ci_cd.platform", [])
    mat = read(lab, MATERIALIZATION)
    if mat is not None:
        rows = re.findall(r"^\| `([^`]+)` \| `(?:governance-check|inventory-drift)\.", mat, re.M)
        add(lab, [f"materialisation: `{r}` — not a ci_cd.platform literal ({' | '.join(q21)})" for r in rows if r not in q21]
            or ([] if rows else ["materialisation: no governance-check platform table found"]))

    # 3 · a platform-specific workflow carries its platform's conditional
    by_slug, found = {}, []
    for k, e in entries:
        m = re.fullmatch(r"workflows/[\w-]+\.([a-z-]+)\.(?:ya?ml|groovy)", k)
        if not m:
            continue
        lit = re.search(r'ci_cd\.platform == "([^"]+)"', e.get("stack_conditional") or "")
        if not lit:
            found.append(f"manifest {k}: a `{m.group(1)}` workflow with no `ci_cd.platform == \"…\"` conditional — it lands on every platform")
        else:
            by_slug.setdefault(m.group(1), set()).add(lit.group(1))
    found += [f"workflows `*.{s}.*` gate on different platforms: {sorted(v)}" for s, v in by_slug.items() if len(v) > 1]
    add("platform workflows", found)

    # 4 · every ci_cd.platform option has its pipeline templates
    conds = [(k, e.get("stack_conditional") or "") for k, e in entries]
    found = [] if q21 else ["the registry offers no ci_cd.platform options"]
    for lit in q21:
        if lit == "None":
            continue
        for kind in ("governance-check", "auto-tag"):
            if not any(k.startswith(f"workflows/{kind}.") and f'"{lit}"' in c for k, c in conds):
                found.append(f"ci_cd.platform offers `{lit}`; no `workflows/{kind}.*` template materialises for it")
    add("pipeline templates", found)

    # 5 · host enum: cloud_provider accepts every hosting.provider option
    lab = "host enum"
    cicd = read(lab, ".context/templates/setup/rules/ci-cd.md")
    if cicd is not None:
        m = re.search(r"cloud_provider: \{\{CLOUD_PROVIDER\}\}\s*#\s*(.+)$", cicd, re.M)
        enum = [x.strip() for x in m.group(1).split("|")] if m else []
        hp = opts.get("hosting.provider", [])
        add(lab, [f"hosting.provider offers `{o}`; rules/ci-cd.md cloud_provider accepts {enum}" for o in hp if o not in enum]
            or ([] if hp else ["the registry offers no hosting.provider options"]))

    # 6 · schema: every resource type the phases compare is in the registry schema
    lab = "infrastructure schema"
    raw = read(lab, ".context/schemas/infrastructure_registry.schema.json")
    if raw is not None:
        def enum_of(node):
            if isinstance(node, dict):
                if isinstance(node.get("type"), dict) and "enum" in node["type"]:
                    return node["type"]["enum"]
                for v in node.values():
                    r = enum_of(v)
                    if r:
                        return r
            return None
        try:
            types = enum_of(json.loads(raw)) or []
        except ValueError:
            types = []
        used = set()
        for rel in files:
            if rel.startswith((".claude/instructions/", ".claude/skills/")):
                try:
                    used.update(re.findall(r"resource\.type == \"([a-z_-]+)\"", (repo / rel).read_text(encoding="utf-8")))
                except (OSError, UnicodeDecodeError):
                    pass
        add(lab, [f"`{t}` used, the schema enum is {types}" for t in sorted(used) if t not in types]
            or ([] if types else ["no resource type enum in the schema"]))

    # 7 · DEVOPS topology labels as Q7 defines them (the codes' names are wording: the instruction holds them)
    lab = "DEVOPS topology"
    disc, dep = read(lab, INSTRUCTION), read(lab, ".claude/instructions/Factory-devops-provision-deploy.instructions.md")
    if disc is not None and dep is not None:
        q7 = dict(re.findall(r"\b(B\d+) \(([^,)]+), \$", disc))
        blk = re.search(r"Per architecture topology[^\n]*\n((?:[ \t]+.*\n)+?)\s*\n", dep)
        found, seen = [], []
        if not blk:
            found.append("Factory-devops-provision-deploy: no `Per architecture topology` block")
        else:
            for code, name in re.findall(r"\b(B\d+) ([^,:]+?)(?=,|:)", blk.group(1)):
                seen.append(code)
                if q7.get(code) != name.strip():
                    found.append(f"DEVOPS labels `{code} {name.strip()}`; Q7 defines `{code} {q7.get(code)}`")
            found += [f"{c} ({q7[c]}) — no build rule" for c in q7 if c not in seen]
            found += [f"{c} — more than one build rule" for c in sorted(set(seen)) if seen.count(c) > 1]
        add(lab, found)

    # 8 · lint-format discovers the rule files as they are named
    lab = "lint-format"
    lf = read(lab, ".context/templates/setup/scripts/lint-format.sh")
    if lf is not None:
        pat = re.search(r"find \.claude/rules [^\n]*-name '([^']+)'", lf)
        rules = [Path(e["target"]).name for _, e in entries if str(e.get("target", "")).startswith(".claude/rules/")]
        add(lab, [] if pat and any(fnmatch.fnmatch(r, pat.group(1)) for r in rules) else
            [f"lint-format.sh searches `.claude/rules` for `{pat.group(1) if pat else '?'}`; the rules land as {sorted(rules)[:4]}…"])

    # 9 · migration layouts the data reader scans (gate.py data, EVOL-071)
    lab = "data layouts"
    vm = read(lab, ".context/templates/setup/scripts/gates/data.py")
    if vm is not None:
        add(lab, [f"gates/data.py does not scan {w}" for w in ('".php"', '"supabase/migrations/**"', '"drizzle/migrations/**"') if w not in vm])

    # 10 · one definition: the milestone literals, the upgrade checksum algorithm
    lab = "one definition"
    bo, usp = read(lab, ".claude/instructions/Factory-backlog-operations.instructions.md"), read(lab, ".context/templates/setup/upgrade_safety_protocol.md")
    found = []
    if bo is not None:
        ms = re.search(r"milestone_strategy: \"\{\{milestone_strategy\}\}\"\s*# Q27\.3: (.+)$", bo, re.M)
        lits = sorted(x.strip() for x in ms.group(1).split("|")) if ms else []
        if lits != opts.get("project_tracking.milestone_strategy"):
            found.append(f"backlog adapter milestone_strategy lists {lits}; the registry offers {opts.get('project_tracking.milestone_strategy')}")
    if usp is not None:
        algos = {a for a, p in (("MD5", r"\bMD5\b"), ("SHA-256", r"\bSHA-?256")) if re.search(p, usp, re.I)}
        if len(algos) != 1:
            found.append(f"upgrade_safety_protocol.md names {sorted(algos) or 'no'} checksum algorithm(s) for one checksum")
    add(lab, found)

    # 11 · the verification loop names no stack: its members are verification.gates (EVOL-067)
    lab = "verification loop"
    bvl = read(lab, ".claude/skills/factory-build-verification/SKILL.md")
    if bvl is not None:
        add(lab, [f"BVL:{n}: `{m.group(0).strip()}` — a stack command in the loop; it belongs in the registry's `configures` rows"
                  for n, line in enumerate(bvl.splitlines(), 1) for m in [STACK_COMMAND.search(line)] if m])

    # 12 · every offered stack literal has a dependency reader (#114, QA-PRE-1)
    from . import dependencies
    have, found = dependencies.readers(), []
    for k in ("backend.runtime", "frontend.framework"):
        found += [] if opts.get(k) else [f"the registry offers no {k} options — nothing compared"]
        found += [f"{k} `{lit}` is offered and has no dependency reader" for lit in opts.get(k, [])
                  if not lit.startswith("None") and lit not in have.get(k, [])]
    add("dependency readers", found)
    return out


def template_tokens(repo: Path, manifest: dict) -> dict:
    """{TOKEN: [template entry, …]} — the UPPER_SNAKE placeholders of every manifest `templates` entry with a target."""
    out: dict = {}
    for k, e in (manifest.get("templates") or {}).items():
        if not isinstance(e, dict) or not e.get("target"):
            continue
        p = repo / TEMPLATE_ROOT / k
        if p.is_file():
            for t in set(TOKEN.findall(p.read_text(encoding="utf-8", errors="replace"))):
                out.setdefault(t, []).append(k)
    return out


def _sources(reg: dict) -> tuple[dict, list[str]]:
    """{TOKEN: [source, …]} across fills, derived fills, constants and the baseline; plus shape findings."""
    src, bad = {}, []
    add = lambda t, where: src.setdefault(t, []).append(where)
    for k, s in list(_specs(reg).items()) + [(k, s) for k, s in (reg.get("derived") or {}).items() if isinstance(s, dict)]:
        f = s.get("fills")
        if f is None:
            continue
        if not isinstance(f, list) or any(not isinstance(t, str) or not TOKEN_NAME.match(t) for t in f) or len(set(f)) != len(f):
            bad.append(f"V10 · `{k}`: fills is a list of distinct UPPER_SNAKE tokens"); continue
        for t in f:
            add(t, f"fills of `{k}`" if k in _specs(reg) else f"fills of derived `{k}`")
    for field in ("constants", "placeholder_baseline"):
        d = reg.get(field, {})
        if not isinstance(d, dict):
            bad.append(f"V10 · `{field}` is not an object {{TOKEN: …}}"); continue
        for t, why in d.items():
            if not TOKEN_NAME.match(t):
                bad.append(f"V10 · {field} `{t}` is not an UPPER_SNAKE token")
            elif field == "constants" and (not isinstance(why, str) or not why.strip()):
                bad.append(f"V10 · constant `{t}` needs its reason")
            elif field == "placeholder_baseline" and not (isinstance(why, str) and BASELINE_VALUE.match(why)):
                bad.append(f"V10 · baseline `{t}`: `{why}` is not `pending #<issue>` or `unsourced`")
            add(t, field)
    return src, bad


def _v10(repo: Path, reg: dict, manifest: dict) -> list[str]:
    toks = template_tokens(repo, manifest)
    src, out = _sources(reg)
    for t in sorted(toks):
        s = src.get(t, [])
        if not s:
            out.append(f"V10 · `{t}` ({', '.join(sorted(toks[t])[:3])}) has no source — add it to a key's `fills`, a derived `fills`, `constants`, or the baseline as `unsourced`")
        elif len(s) > 1:
            out.append(f"V10 · `{t}` has {len(s)} sources ({', '.join(s)}) — one token, one source"
                       + (" — it is now sourced: remove it from the baseline" if "placeholder_baseline" in s else ""))
    out += [f"V10 · `{t}` ({', '.join(s)}) names a token no template with a target carries — remove the entry" for t, s in sorted(src.items()) if t not in toks]
    return out


def _anchors(text: str) -> set[str]:
    return {m.strip() for m in re.findall(r"^#{1,6}\s+(.+?)\s*$", text, re.M)} | {m.strip().rstrip(".:") for m in re.findall(r"\*\*([^*\n]+?)\*\*", text)}


def _v11(repo: Path, reg: dict, fw: tuple | None) -> list[str]:
    rows = reg.get("migrations")
    if rows is None:
        return []
    if not isinstance(rows, list):
        return ["V11 · `migrations` is not a list of {id, since, detect, apply}"]
    p = repo / UPGRADE
    anchors = _anchors(p.read_text(encoding="utf-8", errors="replace")) if p.is_file() else set()
    out, seen = [], set()
    for n, m in enumerate(rows):
        mid = m.get("id") if isinstance(m, dict) else None
        where = f"migration `{mid}`" if mid else f"migration #{n + 1}"
        if not isinstance(m, dict) or set(m) != {"id", "since", "detect", "apply"} or not isinstance(mid, str) or not mid.strip():
            out.append(f"V11 · {where}: a row is exactly {{id, since, detect, apply}}"); continue
        if mid in seen:
            out.append(f"V11 · {where} is declared twice")
        seen.add(mid)
        sv = _semver(m["since"])
        if sv is None:
            out.append(f"V11 · {where}: since `{m['since']}` is not a version (x.y.z)")
        elif fw is not None and sv > fw:
            out.append(f"V11 · {where}: since {m['since']} is above framework_version {'.'.join(map(str, fw))}")
        if m["detect"] != "always" and not (isinstance(m["detect"], str) and DETECT.match(m["detect"])):
            out.append(f"V11 · {where}: detect `{m['detect']}` is not `always` or `<project-relative file>#/<JSON pointer>`")
        if not isinstance(m["apply"], str) or m["apply"].strip() not in anchors:
            out.append(f"V11 · {where}: apply `{m['apply']}` is no heading or bold label of {UPGRADE}")
    return out


def _mcp_rows(where: str, servers) -> list[str]:
    """EVOL-077: an `mcp.servers` row lands in the project's .mcp.json → mcpServers — a local server, pinned, isolated."""
    if servers is None:
        return []
    if not isinstance(servers, dict) or not servers:
        return [f"V12 · {where}: {MCP_POINTER} is {{<server name>: {{command, args}}}}"]
    out = []
    for name, row in servers.items():
        if not MCP_NAME.match(str(name)):
            out.append(f"V12 · {where}: {MCP_POINTER} server name `{name}` is not [a-z0-9-]+ — the harness names its tools mcp__<name>__*")
        if isinstance(row, dict) and row.get("type") == "http":   # EVOL-079: a vendor's remote server, authorised in the harness
            url = row.get("url") if isinstance(row.get("url"), str) else ""
            host = re.match(r"^https://([^/:?#]+)(?:/|$)", url)
            out += [f"V12 · {where}: {MCP_POINTER} `{name}`: `{f}` is not a remote-server field (type, url) — no headers, no env: no credential in the entry" for f in row if f not in ("type", "url")]
            if not host or host.group(1) not in MCP_HOSTS:
                out.append(f"V12 · {where}: {MCP_POINTER} `{name}`: url `{url}` — a remote server is https on one of {', '.join(MCP_HOSTS)}")
            elif "$" in url:
                out.append(f"V12 · {where}: {MCP_POINTER} `{name}`: url `{url}` carries `$` — the harness expands it, so no variable rides to the server")
            continue
        if not isinstance(row, dict) or not isinstance(row.get("command"), str) or not row["command"].strip() \
                or not isinstance(row.get("args"), list) or not all(isinstance(a, str) for a in row["args"]):
            out.append(f"V12 · {where}: {MCP_POINTER} `{name}` is {{command, args}} — a command and a list of string arguments"); continue
        out += [f"V12 · {where}: {MCP_POINTER} `{name}`: `{f}` is not an mcp-server field (command, args) — no env (no credential), no url (no remote server)" for f in row if f not in ("command", "args")]
        if row["command"] != MCP_COMMAND:
            out.append(f"V12 · {where}: {MCP_POINTER} `{name}`: command `{row['command']}` — a browser server runs as `{MCP_COMMAND}` of one pinned package, never a shell or a path")
        pkgs = [a for a in row["args"] if not a.startswith("-")]
        if len(pkgs) != 1 or not MCP_PIN.fullmatch(pkgs[0]):
            out.append(f"V12 · {where}: {MCP_POINTER} `{name}`: the arguments name one package at an exact x.y.z version (`<package>@1.2.3`), got {pkgs or 'none'} — `@latest`, no version or a second package moves under the project")
        out += [f"V12 · {where}: {MCP_POINTER} `{name}`: flag `{a}` is not one of {', '.join(MCP_FLAGS)}" for a in row["args"] if a.startswith("-") and a not in MCP_FLAGS]
        if "--isolated" not in row["args"]:
            out.append(f"V12 · {where}: {MCP_POINTER} `{name}`: no `--isolated` argument — the visual walk runs on a throw-away browser profile")
    return out


def _gate_rows(where: str, rows) -> list[str]:
    if not isinstance(rows, dict):
        return [f"V12 · {where}: configures is {{<config pointer>: value}}"]
    out = []
    ids = rows.get(DC_POINTER)
    if ids is not None and (not isinstance(ids, list) or not all(isinstance(i, str) and DC_UNIVERSAL.match(i) for i in ids)):
        out.append(f"V12 · {where}: {DC_POINTER} is a list of universal class ids [DC-NN, …]")
    out += _mcp_rows(where, rows.get(MCP_POINTER))
    gates = rows.get("verification.gates")
    if gates is None:
        return out
    if not isinstance(gates, dict):
        return [f"V12 · {where}: verification.gates is {{<gate>: {{command, scoped?, red_link?, report?, red?, red_reads?, inline?, was?}}}}"]
    for g, row in gates.items():
        if not isinstance(row, dict):
            out.append(f"V12 · {where}: gate `{g}` is not a row {{command, …}}"); continue
        out += [f"V12 · {where}: gate `{g}`: `{f}` is not a gate-row field ({', '.join(GATE_ROW_FIELDS)}) — reads come from the answers" for f in row if f not in GATE_ROW_FIELDS]
        if not isinstance(row.get("command"), str) or not row["command"].strip():
            out.append(f"V12 · {where}: gate `{g}` has no `command`")
        if "red" in row and not isinstance(row["red"], bool):
            out.append(f"V12 · {where}: gate `{g}`: `red` is true or false — a project's own opt-out; no template row carries it (EVOL-116)")
        if "red_reads" in row and not (isinstance(row["red_reads"], list) and row["red_reads"] and all(isinstance(x, str) for x in row["red_reads"])):
            out.append(f"V12 · {where}: gate `{g}`: `red_reads` is a non-empty list of globs — the test files the row proves")
        inl = row.get("inline")
        if inl is not None and not (isinstance(inl, dict) and set(inl) == {"start", "reads", "scoped"} and isinstance(inl["start"], str) and _is_regex(inl["start"])
                                    and isinstance(inl["reads"], list) and inl["reads"] and isinstance(inl["scoped"], str) and "{paths}" in inl["scoped"]):
            out.append(f"V12 · {where}: gate `{g}`: `inline` is {{start: regex, reads: [globs], scoped: command with {{paths}}}}")
        was = row.get("was")
        if was is not None and not (isinstance(was, dict) and all(f in GATE_ROW_FIELDS and f != "was" and isinstance(v, list) and v for f, v in was.items())):
            out.append(f"V12 · {where}: gate `{g}`: `was` is {{<row field>: [superseded template values]}}")
    return out


def _is_regex(s: str) -> bool:
    try:
        re.compile(s)
        return True
    except re.error:
        return False


def _v12(reg: dict) -> list[str]:
    out = []
    for k, s in _specs(reg).items():
        if "configures" not in s:
            continue
        c, offered = s["configures"], _offered(s)
        db = s.get("decided_by")
        if offered is not None and isinstance(db, dict) and isinstance(db.get("values"), dict):   # a decided value carries its row too (EVOL-081)
            offered = sorted(set(offered) | {canon(v) for v in db["values"].values()})
        if not isinstance(c, dict) or offered is None:
            out.append(f"V12 · `{k}`: configures is {{<option literal>: {{<config pointer>: value}}}} on a key with options"); continue
        for lit, rows in c.items():
            if lit not in offered:
                out.append(f"V12 · `{k}`: configures `{lit}` is not one of its options ({' | '.join(offered)})")
            out += _gate_rows(f"`{k}` = {lit}", rows)
    for k, s in _derived(reg).items():
        if isinstance(s, dict) and "configures" in s:
            out += _gate_rows(f"derived `{k}`", s["configures"])
    return out


def _labels(reg: dict) -> list[str]:
    specs = _specs(reg)
    return sorted({lit for k in STACK_LABEL_KEYS for lit in (_offered(specs.get(k) or {}) or []) if lit not in LABEL_STOP})


def _v13(repo: Path, reg: dict) -> list[str]:
    from . import corpus
    try:
        cat, cs = corpus.catalog(repo, repo / TEMPLATE_CATALOG), corpus.cases(repo / TEMPLATE_CASES)
    except GateFault as e:
        return [f"V13 · {e}"]
    ids, bound, out = [d["id"] for d in cat["dcs"]], _tool_bound(reg), []
    pats = [(lab, re.compile(r"(?<!\w)" + re.escape(lab) + r"(?!\w)")) for lab in _labels(reg)]
    for d in cat["dcs"]:
        i = d["id"]
        if not DC_UNIVERSAL.match(i):
            out.append(f"V13 · {i}: the template catalog holds universal rows only — a `PDC` class is the project's own (rules/defect-prevention.md § Promotion)")
        if d["gate"].strip() in ("", "—", "-"):
            out.append(f"V13 · {i}: no Gate — a universal class enters with its gate, or waits in the issue that builds it (§ Promotion 2)")
        if i not in cs:
            out.append(f"V13 · {i}: no case — add `### {i} — <title>` to {TEMPLATE_CASES} (§ Promotion 6)")
        if i not in bound:
            text = " ".join((d["invariant"], d["gate"], ", ".join(d["paths"])))
            hits = [lab for lab, p in pats if p.search(text)]
            if hits:
                out.append(f"V13 · {i} names {', '.join('`' + h + '`' for h in hits)} — a universal row names no stack or cloud: generalise it, or bind it through the tool's option (`configures → {DC_POINTER}`)")
    out += [f"V13 · case {i} has no row in {TEMPLATE_CATALOG} — add the row or remove the case" for i in cs if i not in ids]
    out += [f"V13 · `configures → {DC_POINTER}` names {i}, not a template row — add the row and its case, or remove the id" for i in bound if i not in ids]
    return out


def _v14(reg: dict) -> list[str]:
    """EVOL-080: once the registry asks a documents source, the asked homes (`deliverables.<category>.home`) are exactly
    the reader's asked categories (gates/documents.py → CATEGORIES) — a category the code compiles or runs is never asked."""
    from .documents import CATEGORIES
    specs = _specs(reg)
    if "documents.source" not in specs:
        return []
    have = {k.split(".")[1] for k in specs if re.fullmatch(r"deliverables\.[a-z_]+\.home", k)}
    want = {c for c, v in CATEGORIES.items() if v["kind"] == "asked"}
    out = [f"V14 · `{c}` is an asked category of the documents reader and not asked here — add `deliverables.{c}.home`" for c in sorted(want - have)]
    out += [f"V14 · `{c}` is asked here, but " + (CATEGORIES[c]["why"] if c in CATEGORIES else "the reader has no such category") +
            " — its only home is the repo; remove `deliverables." + c + ".home`" for c in sorted(have - want)]
    return out


def lint_excludes(command: str) -> tuple[str | None, list[str]]:
    """#261: a lint command's tool (the first word, past `npx`) and the paths its exclusion flags name."""
    try:
        toks = shlex.split(command)
    except ValueError:
        return None, []
    words = [t for t in toks if t != "npx"]
    pats: list[str] = []
    for i, t in enumerate(toks):
        flag, eq, val = t.partition("=")
        if flag in LINT_EXCLUDE_FLAGS:
            val = val if eq else (toks[i + 1] if i + 1 < len(toks) else "")
            pats += [p for p in val.split(",") if p]
    return (Path(words[0]).name if words else None), pats


def lint_anywhere(pat: str, tool: str | None) -> bool:
    """#261, probed (ruff 0.17.4, eslint 9.39.1): a ruff pattern with no `/` matches at any depth; an eslint pattern
    matches at any depth only from `**/`. Every other form names a path from the project root."""
    return pat.startswith("**/") if tool == "eslint" else "/" not in pat


def lint_excluded(path: str, pats: list[str], tool: str | None = None) -> bool:
    """Whether `tool` skips the project-relative `path` under the exclusion patterns: a root-anchored pattern names that
    path or a directory above it; an any-depth one names it from any directory. A leading `/` names nothing. `*` and `?`
    never cross `/`, `**` does."""
    parts = path.split("/")
    for p in pats:
        if p.startswith("/"):
            continue
        q = p.removeprefix("**/").removeprefix("./").strip("/")
        if not q:
            continue
        starts = range(len(parts)) if lint_anywhere(p, tool) else (0,)
        rx = re.compile("".join(".*" if t == "**" else "[^/]*" if t == "*" else "[^/]" if t == "?" else re.escape(t)
                                for t in re.split(r"(\*\*|\*|\?)", q)))
        if any(rx.fullmatch("/".join(parts[i:n])) for i in starts for n in range(i + 1, len(parts) + 1)):
            return True
    return False


def _delivered_owners(manifest: dict) -> dict[str, str | None]:
    """Every path a project receives with its owner: factory-sync's (manifest.delivered, EVOL-136) and each template's target."""
    from .manifest import delivered
    out = {p: r.get("owner") for p, r in delivered(manifest).items()}
    for _, e in (manifest.get("templates") or {}).items():
        if isinstance(e, dict) and isinstance(e.get("target"), str):
            out.setdefault(e["target"], e.get("owner"))
    return out


def _v15(reg: dict, manifest: dict) -> list[str]:
    """#261: a shipped lint row reads the project's own code — it excludes every framework-owned delivered file of its
    language (the project cannot cure one, EVOL-136) and no project-owned one."""
    owners, out = _delivered_owners(manifest), []
    rows = [(f"`{k}` = {lit}", r) for k, s in _specs(reg).items() if isinstance(s.get("configures"), dict)
            for lit, r in s["configures"].items()]
    rows += [(f"derived `{k}`", s["configures"]) for k, s in _derived(reg).items() if isinstance(s, dict) and "configures" in s]
    for where, r in rows:
        lint = ((r or {}).get("verification.gates") or {}).get("lint") if isinstance(r, dict) else None
        if not isinstance(lint, dict) or not isinstance(lint.get("command"), str):
            continue
        tool, pats = lint_excludes(lint["command"])
        if tool not in LINT_READS:
            out.append(f"V15 · {where}: lint tool `{tool}` is not in LINT_READS — name the files it reads"); continue
        out += [f"V15 · {where}: exclusion `{p}` matches at any depth — anchor it at the project root (`./{p}`), or it skips "
                f"the project's own `{p}`" for p in pats if lint_anywhere(p, tool)]
        for p, o in sorted(owners.items()):
            if not p.endswith(LINT_READS[tool]):
                continue
            if o == "framework" and not lint_excluded(p, pats, tool):
                out.append(f"V15 · {where}: lint reads framework-owned `{p}` — exclude it in the command (a project cannot cure it)")
            elif o == "project" and lint_excluded(p, pats, tool):
                out.append(f"V15 · {where}: lint excludes project-owned `{p}` — the gate reads the project's code")
    return out


def validate(repo: Path) -> list[str]:
    """Every finding of V1–V15, each prefixed by its rule. GateFault when the registry or the manifest cannot be read."""
    reg = load_registry(repo)
    manifest = load_manifest(repo)
    fw = _semver(manifest.get("framework_version"))
    out = _v1(reg, fw)
    if fw is None:
        out.append(f"V1 · framework_version `{manifest.get('framework_version')}` in {MANIFEST} is not x.y.z — `since` cannot be held to it")
    return out + _v2(reg) + _v3(reg) + _v4(repo, reg) + _v5(repo, reg, manifest) + _v6(repo, reg) + _v7(repo, reg) + _v8(repo, reg, manifest) + _v9(reg) + _v10(repo, reg, manifest) + _v11(repo, reg, fw) + _v12(reg) + _v13(repo, reg) + _v14(reg) + _v15(reg, manifest)


def render(findings: list[str]) -> str:
    if not findings:
        return "discovery: ok — the registry, its conditions, the instruction, the template and the consumers agree"
    return "\n".join([f"  ❌ {f}" for f in findings] + [f"discovery: RED — {len(findings)} finding(s)"])
